visibleAdminNodes() {
  if (this.formMode !== 'view' || !isCashsaleInReview(this.form)) {
    return []
  }
  if (!this.approvalAllowed || !this.flowKeyNode) {
    return []
  }
  if (this.isTransfer) {
    // 转现售是单审批节点流程，但 SYS_FLOW_CONFIG 绑定的可能是通用模板（节点 key 如
    // Activity_1ksnm9e）也可能是专用流程（taskFinalAudit），key 不固定；
    // 不按 key 匹配：流程查看器存在未办结节点且后端 isApprovalAuth 通过即出终审按钮。
    const conf = TRANSFER_AUDIT_NODES.taskFinalAudit
    return [{
      key: this.flowKeyNode,
      label: conf.label,
      permission: conf.permission,
      api: conf.api || 'approval',
      nodeKey: this.flowKeyNode
    }]
  }
  const node = normalizeCurrentNode(this.flowKeyNode)
  if (!node) return []
  const conf = APPLY_AUDIT_NODES[node]
  if (!conf) return []
  const isAccept = node === 'taskAccept'
  return [{
    key: node,
    label: conf.label,
    permission: conf.permission,
    api: conf.api || 'approval',
    nodeKey: isAccept ? '' : this.flowKeyNode
  }]
},

